/** el-table 树形表格展开/懒加载后的行不计入根级 data，需单独统计实际渲染行数 */
countRenderedTreeRows() {
  const treeChildrenMap = this.$refs.table?.store?.states?.treeData?.children || {}
  const collectCount = (rows) =>
    rows.reduce((total, row) => {
      if (!row) return total
      // el-table 会把 hasChildren 为 true 的「待展开」占位行塞进 children，这类行不实际渲染
      if (row.hasChildren && !(row.children && row.children.length)) return total
      return total + 1 + collectCount(row.children || [])
    }, 0)
  return Object.keys(treeChildrenMap).reduce(
    (total, key) => total + collectCount(treeChildrenMap[key] || []),
    0
  )
},
getBaseTableHeight() {
  const dataLength = this.tableData.length
  const rowHeight = Math.max(this.getMeasuredRowHeight(), this.rowHeight)
  const headerHeight = Math.max(this.getMeasuredHeaderHeight(), this.headerHeight)
  const EMPTY_BLOCK_HEIGHT = 60
  if (dataLength === 0) {
    let calculatedHeight = this.headerCount * headerHeight + EMPTY_BLOCK_HEIGHT + 1
    if (this.isShowSummaryEnabled) {
      calculatedHeight += this.resolvedFooterHeight
    }
    return calculatedHeight
  }
  let calculatedHeight
  if (this.tableTr > 0) {
    // 树形表格展开/收起后根级 data 不变而行数变了，按实际渲染行数计算可视高度
    const renderedRows = Math.max(dataLength, this.countRenderedTreeRows())
    const displayRows = this.fixedViewportRows
      ? Math.max(renderedRows, 1)
      : Math.min(this.tableTr, renderedRows)
    calculatedHeight = displayRows * rowHeight + this.headerCount * headerHeight + 1

  tableTr() {
    this.handleLayoutChange()
  },
  /** 树形结构展开/收起、懒加载子节点后行数变化，但根级 data 引用不变，这里跟进重算高度 */
  tableDataLengthAndRows() {
    this.handleLayoutChange()
  }
},

/** 树形结构展开/收起、懒加载子节点后行数变化，但根级 data 引用不变，这里跟进重算高度 */
renderedTreeRowKeys() {
  const treeChildrenMap = this.$refs.table?.store?.states?.treeData?.children || {}
  return Object.keys(treeChildrenMap)
    .map((key) => `${key}:${(treeChildrenMap[key] || []).length}`)
    .sort()
    .join('|')
},

