/** el-table 树形表格展开/懒加载后的行不计入根级 data，需单独统计实际渲染行数。
 *  el-table 的 treeData.children 形如 { 父 key: { children: [...] } }，叶子行是仅含 children 的空占位对象，
 *  故按「自身是否在某个父级 children 里出现过」判定真实节点，避免把占位对象计成行。
 */
countRenderedTreeRows() {
  const treeData = this.$refs.table?.store?.states?.treeData || {}
  const treeChildrenMap = treeData.children || {}
  const placeholderKeys = new Set()
  Object.keys(treeChildrenMap).forEach((parentKey) => {
    ;(treeChildrenMap[parentKey]?.children || []).forEach((child) => {
      if (child && child[treeData.rowKey || 'id']) placeholderKeys.add(child[treeData.rowKey || 'id'])
    })
  })
  const collectCount = (node) => {
    const children = node?.children || []
    return children.reduce((total, child) => {
      if (!child) return total
      if (child.lazy && !child.children.length) return total
      return total + 1 + collectCount(child)
    }, 0)
  }
  return collectCount(treeData) + placeholderKeys.size - collectCount(treeData)
},

