/** el-table 树形表格展开/懒加载后的行不计入根级 data，需单独统计实际渲染行数。
 *  el-table 的 treeData 形如 { 行 key: { children: [子行 key...], expanded, level, lazy } }，
 *  lazyTreeNodeMap[父 key] 里的每条数据本身也可能带 children（hasChildren 展开后）。
 *  这里按 treeData 的 children 递归统计，并过滤掉尚未加载的懒节点占位。
 */
countRenderedTreeRows() {
  const states = this.$refs.table?.store?.states || {}
  const treeData = states.treeData || {}
  const lazyMap = states.lazyTreeNodeMap || {}
  const lazyColumnIdentifier = states.lazyColumnIdentifier || 'hasChildren'
  // 懒加载子行本身带 hasChildren 时 el-table 用 hasChildren 标记可继续展开，与 children 并存
  const rowChildren = (key) => {
    const lazyChildren = lazyMap[key]
    if (Array.isArray(lazyChildren) && lazyChildren.length) return lazyChildren
    return []
  }
  const walk = (key) => {
    const node = treeData[key]
    if (!node) return 0
    let total = 1
    ;(node.children || []).forEach((childKey) => {
      total += walk(childKey)
    })
    // 未进入 treeData 的懒加载行（展开但尚未 updateTreeData）不计入
    rowChildren(key).forEach((row) => {
      const rowKey = row?.[states.rowKey]
      if (rowKey !== undefined && !treeData[rowKey] && !row[lazyColumnIdentifier]) {
        total += 1
      }
    })
    return total
  }
  return Object.keys(treeData).reduce((total, key) => total + walk(key), 0)
},

